// Package uiform builds huh forms wired to Entire's standard theme and
// accessibility behavior. Centralises the Theme()+WithAccessible() recipe
// so picker UI stays consistent across callers.
package uiform

import (
	"context"
	"errors"
	"fmt"
	"os"

	"charm.land/huh/v2"
)

// IsAccessibleMode reports whether accessibility mode is enabled via the
// ACCESSIBLE environment variable. Set ACCESSIBLE=1 (or any non-empty
// value) to enable simpler prompts that work better with screen readers.
func IsAccessibleMode() bool {
	return os.Getenv("ACCESSIBLE") != ""
}

// Theme returns Entire's standard huh theme.
//
//nolint:ireturn // huh.Theme is an interface in v2
func Theme() huh.Theme {
	return huh.ThemeFunc(huh.ThemeDracula)
}

// New creates a huh form with the standard theme, switching to accessible
// mode when ACCESSIBLE is set. WithAccessible is only available on forms
// (not individual fields), so wrap confirmations and other prompts in a
// form to opt into accessibility.
func New(groups ...*huh.Group) *huh.Form {
	form := huh.NewForm(groups...).WithTheme(Theme())
	if IsAccessibleMode() {
		form = form.WithAccessible(true)
	}
	return form
}

// PromptYN renders a Confirm form with the standard theme/accessibility
// behavior and returns the user's answer. On user cancellation (Ctrl+C or
// context.Canceled) returns (false, nil) so callers treat it as a "no";
// on real form errors the error is returned wrapped.
func PromptYN(ctx context.Context, question string, def bool) (bool, error) {
	answer := def
	form := New(huh.NewGroup(
		huh.NewConfirm().
			Title(question).
			Value(&answer),
	))
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
			return false, nil
		}
		return false, fmt.Errorf("confirm form: %w", err)
	}
	return answer, nil
}

package cli

import (
	"errors"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

// newCheckpointGroupCmd builds the `entire checkpoint` parent command and
// registers list/explain/search as children, plus the deprecated rewind.
func newCheckpointGroupCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:     "checkpoint",
		Aliases: []string{"cp", "checkpoints"},
		Short:   "Inspect, rewind, and search checkpoints",
		Long: `Operations on checkpoints — the persistent records of agent work tied to commits.

Commands:
  list     List checkpoints on the current branch
  explain  Explain a checkpoint, commit, or session
  search   Search checkpoints (semantic + keyword)

Examples:
  entire checkpoint list
  entire checkpoint explain <id|sha>
  entire checkpoint search "fix login"`,
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
				return errors.New("not a git repository")
			}
			return nil
		},
	}

	cmd.AddCommand(newCheckpointListCmd())
	cmd.AddCommand(newExplainCmd())
	cmd.AddCommand(newRewindCmd())
	cmd.AddCommand(newCheckpointSearchCmd())

	return cmd
}

func newCheckpointSearchCmd() *cobra.Command {
	cmd := newSearchCmd()
	cmd.Hidden = false
	return cmd
}

// newCheckpointListCmd wraps the existing branch-default list view.
func newCheckpointListCmd() *cobra.Command {
	var sessionFlag string
	var noPagerFlag bool

	cmd := &cobra.Command{
		Use:   "list",
		Short: "List checkpoints on the current branch",
		Long: `List checkpoints on the current branch.

Optionally filter by session ID with --session.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
				return nil
			}
			return runExplainBranchWithFilter(cmd.Context(), cmd.OutOrStdout(), noPagerFlag, sessionFlag)
		},
	}

	cmd.Flags().StringVar(&sessionFlag, "session", "", "Filter checkpoints by session ID (or prefix)")
	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
	return cmd
}

